	// Someone with a copy of the database must not end up with working links.
	srv := newServerUnderTest(t)
	enableLinks(t, srv, true)
	documentID := ownedDocument(t, srv, "문서")
	token, _ := makeLink(t, srv, documentID, map[string]any{})

